#!/usr/bin/env python3
# Run as root on the deployed server. Only modifies hengzi-app; never clears DB.
from pathlib import Path
import base64,zlib,json,shutil,datetime,sqlite3,re,subprocess,os
root=Path('/opt/hengzi-app');dbpath=root/'data/hengzi.db'
assert root.is_dir() and dbpath.is_file(),'Missing app/database; stopped'
backup=Path('/opt/hengzi-backups')/('display-fix-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S'))
backup.mkdir(parents=True,mode=0o700);backup.parent.chmod(0o700)
def counts():
 with sqlite3.connect('file:'+str(dbpath)+'?mode=ro',uri=True) as db:
  assert db.execute('PRAGMA integrity_check').fetchone()[0]=='ok'
  return {t:db.execute('SELECT COUNT(*) FROM '+t).fetchone()[0] for t in ['accounts','transactions','budgets','valuations','import_batches']}
before=counts();print('Database before:',before)
with sqlite3.connect(dbpath) as src,sqlite3.connect(backup/'hengzi.db') as dest:src.backup(dest)
payload=json.loads(zlib.decompress(base64.b64decode('')))
for name in payload:
 target=(root/'server.js') if name=='server.js' else (root/'public'/name);shutil.copy2(target,backup/name)
 target.write_text(payload[name]);target.chmod(0o644)
server=root/'server.js'
s=server.read_text();s=re.sub(r'^seed\(\);[ \t]*$','// 演示数据初始化已禁用',s,flags=re.M)
assert not re.search(r'^seed\(\);',s,re.M),'Seed call not disabled'
server.write_text(s)
subprocess.run(['docker','restart','hengzi-fm'],check=True)
after=counts();print('Database after:',after)
assert before==after,'Record counts changed; inspect backup'
print('Display fix installed; database records retained; backup:',backup)
print('Refresh browser with Cmd+Shift+R or Ctrl+Shift+R. No blog/sub2api changes.')
